select case when year(s.started_at) < 2024 then 'before_2024' when year(s.started_at) = 2024 then '2024' else 'after_2024' end started_cohort, case when s.browser in ('Firefox', 'Chrome') then 'core' else 'other' end browser_group, max(we.event_time) latest_event_time from web_events we join sessions s on we.session_id = s.id group by case when year(s.started_at) < 2024 then 'before_2024' when year(s.started_at) = 2024 then '2024' else 'after_2024' end, case when s.browser in ('Firefox', 'Chrome') then 'core' else 'other' end;
